(()=>{'use strict';
const config=window.QUANTEX_SITE||{channels:{},catalog:[]};
function safeInvitation(value,channel){try{const u=new URL(value);const hosts=channel==='whatsapp'?['chat.whatsapp.com']:['t.me','telegram.me'];return u.protocol==='https:'&&!u.username&&!u.password&&hosts.includes(u.hostname)&&u.pathname.length>1?u.href:null;}catch{return null;}}
document.querySelectorAll('[data-channel]').forEach(card=>{const channel=card.dataset.channel;const link=card.querySelector('a');if(!link)return;const safe=safeInvitation(config.channels?.[channel],channel);if(safe)link.href=safe;else{const status=document.createElement('span');status.className='channel-status';status.textContent='Not available yet';link.replaceWith(status);card.querySelector('h3').textContent='Invitation pending';card.querySelector('p').textContent='The official group invitation has not been added yet. Ordering is not open through this channel.';}});
const nav=document.querySelector('#nav'),toggle=document.querySelector('#menu-toggle');
if(nav&&toggle){const small=matchMedia('(max-width:900px)');let open=false;nav.classList.add('is-enhanced');function update(){toggle.hidden=!small.matches;nav.hidden=small.matches&&!open;toggle.setAttribute('aria-expanded',String(small.matches&&open));}function close(restore=false){open=false;update();if(restore)toggle.focus();}toggle.addEventListener('click',()=>{open=!open;update();});small.addEventListener('change',()=>{open=false;update();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&open){close(true);event.preventDefault();}});document.addEventListener('click',event=>{if(open&&!nav.contains(event.target)&&!toggle.contains(event.target))close();});nav.addEventListener('click',event=>{if(event.target.closest('a'))close();});update();}
document.querySelectorAll('[data-catalog]').forEach(catalog=>{const cards=[...catalog.querySelectorAll('[data-product]')],filters=[...catalog.querySelectorAll('[data-filter]')],search=catalog.querySelector('#search'),status=catalog.querySelector('#result-count'),empty=catalog.querySelector('[data-empty]');let category='all';function update(){const query=(search?.value||'').trim().toLocaleLowerCase();let count=0;cards.forEach(card=>{const shown=(category==='all'||card.dataset.category===category)&&card.dataset.search.includes(query);card.hidden=!shown;if(shown)count++;});filters.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.filter===category)));if(status)status.textContent=`${count} ${count===1?'compound':'compounds'}${query?' matching your search':''}`;if(empty)empty.hidden=count!==0;}filters.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;update();}));search?.addEventListener('input',update);catalog.querySelector('[data-reset-search]')?.addEventListener('click',()=>{category='all';if(search){search.value='';search.focus();}update();});catalog.querySelectorAll('[data-enhanced]').forEach(el=>el.hidden=false);update();});
const selected=document.querySelector('[data-selected-compound]');if(selected){const slug=new URLSearchParams(location.search).get('compound');const product=(config.catalog||[]).find(p=>p.slug===slug);if(product){const text=document.createElement('span');text.textContent=`Your enquiry: ${product.name}. `;const link=document.createElement('a');link.href=(config.basePath||'')+'/products/'+product.slug+(config.directoryRoutes?'/':'');link.textContent='Review compound details';selected.replaceChildren(text,link);selected.hidden=false;}}
})();
